/usr/bin/bash -lc "cat > verification/keyboard.mjs <<'EOF'
import { browser } from '../tools/browser.mjs';
import { writeFile } from 'node:fs/promises';
const b=await browser(),results=[];
const check=async(name,expression)=>{const result=await b.evaluate(expression);results.push({name,result});if("'!result)throw Error(name);};
const key=async(key,code=key,shift=false)=>{await b.send('"'Input.dispatchKeyEvent',{type:'keyDown',key,code,modifiers:shift?8:0});await b.send('Input.dispatchKeyEvent',{type:'keyUp',key,code,modifiers:shift?8:0});};
try {
 await b.navigate('index.html','',375);
 await b.evaluate("'`document.querySelector('"'button[data-action=\"edit\"]').focus()"'`);
 await key('"'Enter');
 await check('Keyboard Enter opens editor and focuses name',"'`document.querySelector('"'dialog').open && document.activeElement.name==='name'"'`);
 await b.evaluate(`document.querySelector('"'[data-action=\"save\"]').focus()"'`);await key('"'Tab');
 await check('Tab wraps within native dialog',"'`document.querySelector('"'dialog').contains(document.activeElement)"'`);
 await key('"'Escape');
 await check('Escape closes unchanged editor and returns invoker',"'`!document.querySelector('"'dialog').open && document.activeElement.dataset.action==='edit'"'`);
 await key('"'Enter');await b.evaluate("'`document.querySelector('"'[name=\"name\"]').value='keyboard draft'"'`);await key('"'Escape');
 await check('Escape protects unsaved draft',"'`document.querySelector('"'dialog').open && document.activeElement.dataset.action==='keep'"'`);
 await key('"'Enter');
 await check('Keep editing keyboard action',"'`document.activeElement.name==='"'name' && document.querySelector('[name=\"name\"]').value==='keyboard draft'"'`);
 await b.send('"'Emulation.setDeviceMetricsOverride',{width:375,height:400,deviceScaleFactor:1,mobile:false});
 await check('375x400: Save and Cancel visible',"'`[...document.querySelectorAll('"'.dialog-foot button')].every(b=>{const r=b.getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight})"'`);
 await b.evaluate(`document.querySelector('"'[name=\"price\"]').focus();document.querySelector('[name=\"price\"]').scrollIntoView({block:'nearest'})"'`);
 await check('"'375x400: price correction reachable',"'`(()=>{const r=document.querySelector('"'[name=\"price\"]').getBoundingClientRect();const a=document.querySelector('.dialog-body').getBoundingClientRect();return r.top>=a.top&&r.bottom<=a.bottom})()"'`);
 await b.evaluate(`document.querySelector('"'dialog [data-action=\"cancel\"]').click()"'`);
 await check('"'375x400: discard choices reachable',"'`[...document.querySelectorAll('"'.discard-actions button')].every(b=>{const r=b.getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight})"'`);
 await b.evaluate(`document.querySelector('"'[data-action=\"discard\"]').click()"'`);
 await b.send('"'Emulation.setDeviceMetricsOverride',{width:320,height:640,deviceScaleFactor:1,mobile:false});
 await check('320px: no page overflow',"'`document.documentElement.scrollWidth<=innerWidth`);
 await b.evaluate(`document.querySelector('"'#table-view').click();document.querySelector('.table-region').focus()"'`);
 await key('"'ArrowRight');await new Promise(r=>setTimeout(r,150));
 await check('Keyboard horizontal comparison scrolling',"'`document.querySelector('"'.table-region').scrollLeft>0"'`);
 await b.send('"'Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:1});
 await b.evaluate("'`document.querySelector('"'.table-region').scrollLeft=0;document.querySelector('.table-region').scrollIntoView()"'`);
 const point=await b.evaluate(`(()=>{const r=document.querySelector('"'.table-region').getBoundingClientRect();return {x:280,y:Math.max(50,r.top+120)}})()"'`);
 await b.send('"'Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:point.x,y:point.y}]});
 for(const x of [230,180,130,80])await b.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x,y:point.y}]});
 await b.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});
 await check('Touch swipe scrolls comparison',"'`document.querySelector('"'.table-region').scrollLeft>0"'`);
 await b.navigate('"'index.html','',375);
 await b.evaluate("'`document.documentElement.style.fontSize='"'200%';document.querySelectorAll('p,button,input,select,label,td,h1,h2').forEach(el=>el.style.fontSize='1rem')"'`);
 await check('"'Enlarged text: no page overflow',"'`document.documentElement.scrollWidth<=innerWidth`);
 const img=await b.send('"'Page.captureScreenshot',{format:'png'});await writeFile(new URL('enlarged-text.png',import.meta.url),Buffer.from(img.data,'base64'));
 results.push({name:'Runtime exceptions',result:b.events.filter(e=>e.method==='Runtime.exceptionThrown')});
}finally{await writeFile(new URL('keyboard-results.json',import.meta.url),JSON.stringify(results,null,2));await b.close();}
console.log(JSON.stringify(results,null,2));
EOF
